169	        } else {
170	            if (selectedSiteTitles?.includes(siteUrl)) setSelectedSiteTitles(selectedSiteTitles.filter((t: any) => t !== siteUrl));
171	        }
172	    };
173	
174	    const getCoverImageUrl = (taskList: any): string | null => {
175	        if (!taskList) return null;
176	        const cover = taskList?.Item_x005F_x0020_Cover || taskList?.Item_x0020_Cover || taskList?.coverImage || taskList?.ItemCoverURL;
177	        if (!cover) return null;
178	
179	        let rawUrl: string | null = null;
180	        if (typeof cover === 'object') {
181	            rawUrl = cover?.Url || cover?.url || cover?.URI || null;
182	        } else if (typeof cover === 'string') {
183	            const trimmed = cover.trim();
184	            if (trimmed.startsWith('{')) {
185	                try {
186	                    const parsed = JSON.parse(trimmed);
187	                    rawUrl = parsed?.Url || parsed?.url || null;
188	                } catch (e) {
189	                    rawUrl = null;
190	                }
191	            } else {
192	                rawUrl = trimmed;
193	            }
194	        }
195	
196	        if (!rawUrl) return null;
197	
198	        if (rawUrl.startsWith('https://') || rawUrl.startsWith('http://')) {
199	            return rawUrl;
200	        }
201	        if (rawUrl.startsWith('//')) {
202	            return `https:${rawUrl}`;
203	        }
