if (activeSites && activeSites.length > 0 && activeSitesSelectedItems.length === 0 && useForOMTTool === true) {
    // Default selection is decided PER TASK LIST (metadata row), not per site.
    // A task list is pre-checked only when its OWN IsVisible === true; a task list whose
    // IsVisible !== true (false/null/undefined/no matching row) stays unchecked even if a
    // sibling on the same site is visible. All sites/task lists still remain LISTED (see render).
    const defaultTaskLists = activeSites.flatMap((siteData: any) =>
        (siteData?.TaskLists || [])
            .filter((taskList: any) => taskList?.IsVisible === true)
            .map((taskList: any) => ({
                siteTitle: siteData.Site.Title, siteUrl: siteData.Site.Url, siteId: siteData.Site.SiteId, webId: siteData.Site.WebId,
                taskListTitle: taskList.Title, taskListId: taskList.Id, taskListUrl: taskList.Url, coverImage: taskList.Item_x005F_x0020_Cover || taskList.Item_x0020_Cover || taskList.coverImage
            }))
    );
    setActiveSitesSelectedItems(defaultTaskLists);
    // A site's checkbox is checked only when EVERY one of its task lists ended up selected
    // (mirrors handleTaskListSelect's all-lists-selected logic). Partial/none → unchecked.
    const fullySelectedSiteUrls = activeSites
        .filter((siteData: any) => {
            const lists = siteData?.TaskLists || [];
            return lists.length > 0 && lists.every((tl: any) => defaultTaskLists.some((item: any) => item.taskListId === tl.Id));
        })
        .map((siteData: any) => siteData.Site.Url);
    setSelectedSiteTitles(fullySelectedSiteUrls);
}

